methodsBefore.BmadProgressCoordinator:
reconcile() {
	for (const [id, lease] of this.leases) lease.reconcile().then((fresh) => {
		if (!this.closing && !this.jobs.has(id) && (!fresh || this.pending.has(id) || this.project(id).freshness === "uncertain")) {
			this.pending.add(id);
			this.schedule(id);
		}
	});
}

methodsBefore.BmadContextCoordinator:
async consultSelection(id, signal) {
	const generation = this.generations.get(id) ?? 0;
	await this.restore(id);
	const selected = this.project(id).selection;
	if (!selected) throw dialogueFailure("CONTEXT_MISMATCH");
	const project = await this.deps.application.dialogueProject(id);
	signal.throwIfAborted();
	const observation = await (this.deps.observeConsultation ?? this.deps.observe)(id, project.rootPath, signal);
	signal.throwIfAborted();
	if (!isBmadContextObservation(observation) || observation.projectId !== id || observation.rootPath.toLowerCase().replaceAll("\\", "/") !== project.rootPath.toLowerCase().replaceAll("\\", "/")) throw dialogueFailure("PROFILE_CHANGED");
	const destination = await this.deps.application.dialogueProject(id);
	signal.throwIfAborted();
	const current = this.project(id);
	if (this.closing || destination.rootPath !== project.rootPath || (this.generations.get(id) ?? 0) !== generation || current.selection?.revision !== selected.revision) throw dialogueFailure("PROFILE_CHANGED");
	this.update(id, {
		observation,
		status: "ready"
	});
	const result = this.project(id);
	if (selectionValidity(result) !== "valid") throw dialogueFailure("CONTEXT_MISMATCH");
	return structuredClone(result);
}

methodsAfter.BmadProgressCoordinator:
reconcile() {
	for (const id of this.armed) Promise.resolve(this.leases.get(id)?.reconcile() ?? true).then((fresh) => {
		if (!this.closing && !this.jobs.has(id) && (!fresh || this.pending.has(id) || this.project(id).freshness === "uncertain")) {
			this.pending.add(id);
			this.schedule(id);
		}
	});
}

methodsAfter.BmadContextCoordinator:
async consultSelection(id, signal) {
	const generation = this.generations.get(id) ?? 0;
	await this.restore(id);
	const selected = this.project(id).selection;
	if (!selected) throw dialogueFailure("CONTEXT_MISMATCH");
	const project = await this.deps.application.dialogueProject(id);
	signal.throwIfAborted();
	const observation = await (this.deps.observeConsultation ?? this.deps.observe)(id, project.rootPath, signal);
	signal.throwIfAborted();
	if (!isBmadContextObservation(observation) || observation.projectId !== id || observation.rootPath.toLowerCase().replaceAll("\\", "/") !== project.rootPath.toLowerCase().replaceAll("\\", "/")) throw dialogueFailure("PROFILE_CHANGED");
	const assertCurrent = async () => {
		const destination = await this.deps.application.dialogueProject(id);
		signal.throwIfAborted();
		const selection = this.project(id).selection;
		if (this.closing || destination.rootPath !== project.rootPath || (this.generations.get(id) ?? 0) !== generation || !selection || selection.revision !== selected.revision || selection.initiativeId !== selected.initiativeId || selection.rootIdentity !== selected.rootIdentity || selection.rootPath !== selected.rootPath) throw dialogueFailure("PROFILE_CHANGED");
	};
	let lease;
	try {
		await assertCurrent();
		lease = await this.deps.observation?.attach(observation, (health) => this.invalidate(id, health));
		await assertCurrent();
		const fresh = lease ? await lease.reconcile() : true;
		await assertCurrent();
		if (!fresh) throw dialogueFailure("PROFILE_CHANGED");
		const health = lease?.health ?? "unarmed", displaced = this.leases.get(id);
		if (displaced !== lease) displaced?.close();
		if (lease) {
			this.leases.set(id, lease);
			lease = void 0;
		} else this.leases.delete(id);
		this.update(id, {
			observation,
			status: "ready",
			freshness: "current",
			monitoring: health
		});
		const result = this.project(id);
		if (selectionValidity(result) !== "valid") throw dialogueFailure("CONTEXT_MISMATCH");
		return structuredClone(result);
	} finally {
		lease?.close();
	}
}
